from __future__ import annotations

"""Per-spend-day spend summaries finance uses to reconcile against budgets.

Finance closes each day and checks that no campaign spent more than its daily
budget on its own spend day. The report walks the ledger, groups recorded spend
by the account-timezone spend day, and rolls it up per campaign and per ad set.
A day is flagged when a campaign's total spend on that day exceeds the budget
that governed it.

Totals here must reconcile with the ledger: the per-ad-set numbers in a day's
campaign block sum to that campaign's day total, and a day's campaign totals
sum to the day's account total.
"""

from dataclasses import dataclass

from budget_models import AdAccount, Campaign
from day_boundary import local_day_key
from money import Money, sum_money
from spend_ledger import SpendLedger


@dataclass(frozen=True)
class CampaignDayLine:
    campaign_id: str
    budget: Money | None
    total_spent: Money
    per_adset: dict[str, Money]
    over_budget: bool


@dataclass(frozen=True)
class DayReport:
    day_key: str
    account_total: Money
    campaigns: tuple[CampaignDayLine, ...]

    def campaign_line(self, campaign_id: str) -> CampaignDayLine:
        for line in self.campaigns:
            if line.campaign_id == campaign_id:
                return line
        raise KeyError(campaign_id)

    def flagged_campaigns(self) -> list[str]:
        return [c.campaign_id for c in self.campaigns if c.over_budget]


def _governing_budget(campaign: Campaign) -> Money | None:
    """The budget a whole campaign's day total is judged against.

    For CBO it is the campaign budget. For a non-CBO campaign the day total is
    judged against the sum of its ad sets' own daily budgets.
    """

    if campaign.uses_cbo:
        return campaign.cbo_daily_budget
    budgets = [a.daily_budget for a in campaign.adsets if a.daily_budget is not None]
    if not budgets:
        return None
    return sum_money(budgets)


def campaign_day_line(
    campaign: Campaign, ledger: SpendLedger, day_key: str
) -> CampaignDayLine:
    breakdown = ledger.adset_breakdown(campaign.adset_ids(), day_key)
    total = sum_money([breakdown[aid] for aid in campaign.adset_ids()])
    budget = _governing_budget(campaign)
    over = budget is not None and total.cents > budget.cents
    return CampaignDayLine(
        campaign_id=campaign.campaign_id,
        budget=budget,
        total_spent=total,
        per_adset=breakdown,
        over_budget=over,
    )


def day_report(account: AdAccount, ledger: SpendLedger, day_key: str) -> DayReport:
    lines = [campaign_day_line(c, ledger, day_key) for c in account.campaigns]
    account_total = sum_money([line.total_spent for line in lines])
    return DayReport(
        day_key=day_key,
        account_total=account_total,
        campaigns=tuple(lines),
    )


def days_with_spend(account: AdAccount, ledger: SpendLedger) -> list[str]:
    """All spend days present in the ledger, in the account's timezone."""

    keys = {local_day_key(account.timezone, e.charged_at) for e in ledger.all_events()}
    return sorted(keys)


def full_report(account: AdAccount, ledger: SpendLedger) -> list[DayReport]:
    return [day_report(account, ledger, key) for key in days_with_spend(account, ledger)]


def reconciles(report: DayReport) -> bool:
    """True when the report's internal totals add up consistently."""

    campaign_sum = 0
    for line in report.campaigns:
        adset_sum = sum(m.cents for m in line.per_adset.values())
        if adset_sum != line.total_spent.cents:
            return False
        campaign_sum += line.total_spent.cents
    return campaign_sum == report.account_total.cents

