from __future__ import annotations

"""Domain model for accounts, campaigns, ad sets, and their daily budgets.

The hierarchy mirrors the ad platform: an account owns campaigns, a campaign
owns ad sets. Budgets can live at two levels. A campaign with Campaign Budget
Optimization (CBO) carries a single daily budget that the platform spreads
across its ad sets automatically; the per-ad-set amounts float, but their sum
for a spend day must not exceed the campaign daily budget. A campaign without
CBO instead has a daily budget on each ad set directly.

The account carries the timezone that defines the spend day. Everything that
follows derives the spend day from the account's zone, never from UTC or the
server clock.
"""

from dataclasses import dataclass, field

from account_timezone import AccountTimezone
from money import Money


@dataclass(frozen=True)
class AdSet:
    """A delivery unit inside a campaign.

    ``daily_budget`` is only meaningful for non-CBO campaigns. ``min_daily`` is
    an optional floor the allocator should try to keep funded before spreading
    headroom; ``paused`` ad sets are not eligible to receive spend.
    """

    adset_id: str
    name: str
    daily_budget: Money | None = None
    min_daily: Money = field(default_factory=Money.zero)
    paused: bool = False

    def __post_init__(self) -> None:
        if self.daily_budget is not None and self.daily_budget.is_negative():
            raise ValueError("ad set daily_budget cannot be negative")
        if self.min_daily.is_negative():
            raise ValueError("min_daily cannot be negative")

    def is_eligible(self) -> bool:
        return not self.paused


@dataclass(frozen=True)
class Campaign:
    """A campaign owning one or more ad sets.

    When ``cbo_daily_budget`` is set the campaign uses CBO: the budget caps the
    sum of ad-set spend across the spend day. When it is ``None`` each ad set
    enforces its own ``daily_budget`` independently.
    """

    campaign_id: str
    name: str
    adsets: tuple[AdSet, ...]
    cbo_daily_budget: Money | None = None

    def __post_init__(self) -> None:
        if not self.adsets:
            raise ValueError("a campaign needs at least one ad set")
        ids = [a.adset_id for a in self.adsets]
        if len(ids) != len(set(ids)):
            raise ValueError("duplicate adset_id within campaign")
        if self.cbo_daily_budget is not None and self.cbo_daily_budget.is_negative():
            raise ValueError("cbo_daily_budget cannot be negative")

    @property
    def uses_cbo(self) -> bool:
        return self.cbo_daily_budget is not None

    def adset(self, adset_id: str) -> AdSet:
        for a in self.adsets:
            if a.adset_id == adset_id:
                return a
        raise KeyError(adset_id)

    def adset_ids(self) -> list[str]:
        return [a.adset_id for a in self.adsets]

    def eligible_adsets(self) -> list[AdSet]:
        return [a for a in self.adsets if a.is_eligible()]

    def owns_adset(self, adset_id: str) -> bool:
        return any(a.adset_id == adset_id for a in self.adsets)

    def daily_cap_for(self, adset_id: str) -> Money | None:
        """The applicable daily cap for a single ad set.

        For CBO this is the shared campaign budget (the sum cap), surfaced here
        so a caller asking about one ad set still sees the governing number.
        For non-CBO it is the ad set's own budget.
        """

        if self.uses_cbo:
            return self.cbo_daily_budget
        return self.adset(adset_id).daily_budget


@dataclass(frozen=True)
class AdAccount:
    """An advertiser account that owns campaigns and defines the spend day.

    The ``timezone`` here is the source of truth for what calendar day a spend
    event belongs to. Two accounts billed at the same UTC instant can place that
    spend on different spend days if their zones differ.
    """

    account_id: str
    name: str
    timezone: AccountTimezone
    campaigns: tuple[Campaign, ...] = ()

    def __post_init__(self) -> None:
        ids = [c.campaign_id for c in self.campaigns]
        if len(ids) != len(set(ids)):
            raise ValueError("duplicate campaign_id within account")

    def campaign(self, campaign_id: str) -> Campaign:
        for c in self.campaigns:
            if c.campaign_id == campaign_id:
                return c
        raise KeyError(campaign_id)

    def campaign_of_adset(self, adset_id: str) -> Campaign:
        for c in self.campaigns:
            if c.owns_adset(adset_id):
                return c
        raise KeyError(f"no campaign owns adset {adset_id}")

    def all_adset_ids(self) -> list[str]:
        ids: list[str] = []
        for c in self.campaigns:
            ids.extend(c.adset_ids())
        return ids

    def with_campaigns(self, campaigns: tuple[Campaign, ...]) -> "AdAccount":
        return AdAccount(self.account_id, self.name, self.timezone, campaigns)


def build_adset(
    adset_id: str,
    name: str = "",
    daily_budget_cents: int | None = None,
    min_daily_cents: int = 0,
    paused: bool = False,
) -> AdSet:
    budget = Money(daily_budget_cents) if daily_budget_cents is not None else None
    return AdSet(
        adset_id=adset_id,
        name=name or adset_id,
        daily_budget=budget,
        min_daily=Money(min_daily_cents),
        paused=paused,
    )


def build_campaign(
    campaign_id: str,
    adsets: list[AdSet],
    cbo_daily_budget_cents: int | None = None,
    name: str = "",
) -> Campaign:
    cbo = Money(cbo_daily_budget_cents) if cbo_daily_budget_cents is not None else None
    return Campaign(
        campaign_id=campaign_id,
        name=name or campaign_id,
        adsets=tuple(adsets),
        cbo_daily_budget=cbo,
    )


def build_account(
    account_id: str,
    timezone: AccountTimezone,
    campaigns: list[Campaign] | None = None,
    name: str = "",
) -> AdAccount:
    return AdAccount(
        account_id=account_id,
        name=name or account_id,
        timezone=timezone,
        campaigns=tuple(campaigns or []),
    )

