campaign. The platform then decides how much of it each ad set may spend. The
hard rule is that the campaign daily budget caps the *sum* of ad-set spend for
the spend day; individual ad sets have no fixed cap of their own beyond an
optional minimum the allocator tries to keep funded.

This module answers two questions for a given spend day:

* given what each ad set has already spent, how much campaign budget is left to
  hand out across the campaign as a whole;
* how should the remaining headroom be split across eligible ad sets.

The day passed in is the account-timezone spend day; the already-spent figures
come from the ledger for that same day.
"""

from dataclasses import dataclass

from budget_models import Campaign
from money import Money, sum_money
from spend_ledger import SpendLedger


@dataclass(frozen=True)
class AdSetAllocation:
    adset_id: str
    already_spent: Money
    headroom: Money

    def total_allowed(self) -> Money:
        return self.already_spent.add(self.headroom)


@dataclass(frozen=True)
class CampaignAllocation:
    campaign_id: str
    day_key: str
    campaign_budget: Money
    spent_total: Money
    remaining: Money
    per_adset: tuple[AdSetAllocation, ...]

    def allocation_for(self, adset_id: str) -> AdSetAllocation:
        for a in self.per_adset:
            if a.adset_id == adset_id:
                return a
        raise KeyError(adset_id)

    def headroom_map(self) -> dict[str, Money]:
        return {a.adset_id: a.headroom for a in self.per_adset}

    def total_headroom(self) -> Money:
        return sum_money([a.headroom for a in self.per_adset])


class CboAllocator:
    """Spreads a CBO campaign budget across eligible ad sets for a day."""

    def __init__(self, ledger: SpendLedger) -> None:
        self._ledger = ledger

    def _spent_per_adset(
        self, campaign: Campaign, day_key: str
    ) -> dict[str, Money]:
        return self._ledger.adset_breakdown(campaign.adset_ids(), day_key)

    def allocate(self, campaign: Campaign, day_key: str) -> CampaignAllocation:
        """Compute the day's allocation for a CBO campaign.

        ``remaining`` is the campaign budget minus the sum already spent across
        every ad set. Remaining headroom is then offered to eligible ad sets,
        with each ad set's minimum honoured first before the rest is spread.
        """

        if not campaign.uses_cbo:
            raise ValueError("allocate is only for CBO campaigns")

        budget = campaign.cbo_daily_budget
        assert budget is not None  # narrowed by uses_cbo
        spent_by_adset = self._spent_per_adset(campaign, day_key)

        eligible = campaign.eligible_adsets()
        eligible_ids = [a.adset_id for a in eligible]

        spent_total = sum_money(
            [spent_by_adset.get(aid, Money.zero()) for aid in campaign.adset_ids()]
        )
        remaining_pool = budget.subtract(spent_total).clamp_non_negative()

        # First reserve each eligible ad set's minimum (above what it already
        # spent), drawing from the remaining pool in declaration order.
        reserved: dict[str, Money] = {aid: Money.zero() for aid in eligible_ids}
        pool = remaining_pool
        for adset in eligible:
            already = spent_by_adset.get(adset.adset_id, Money.zero())
            shortfall = adset.min_daily.subtract(already).clamp_non_negative()
            grant = shortfall.min_with(pool)
            reserved[adset.adset_id] = grant
            pool = pool.subtract(grant)

        # Spread whatever is left evenly across eligible ad sets.
        spread = self._even_spread(pool, eligible_ids)

        per_adset: list[AdSetAllocation] = []
        for aid in campaign.adset_ids():
            already = spent_by_adset.get(aid, Money.zero())
            if aid in eligible_ids:
                headroom = reserved[aid].add(spread.get(aid, Money.zero()))
            else:
                headroom = Money.zero()
            per_adset.append(
                AdSetAllocation(
                    adset_id=aid,
                    already_spent=already,
                    headroom=headroom,
                )
            )

        return CampaignAllocation(
            campaign_id=campaign.campaign_id,
            day_key=day_key,
            campaign_budget=budget,
            spent_total=spent_total,
            remaining=remaining_pool,
            per_adset=tuple(per_adset),
        )

    @staticmethod
    def _even_spread(pool: Money, adset_ids: list[str]) -> dict[str, Money]:
        """Split a pool of cents as evenly as possible across ad sets.

        Leftover cents after the even split go to the earliest ad sets in
        declaration order so the sum of the split equals the pool exactly.
        """

        if not adset_ids or pool.cents <= 0:
            return {aid: Money.zero() for aid in adset_ids}
        base, extra = divmod(pool.cents, len(adset_ids))
        result: dict[str, Money] = {}
        for index, aid in enumerate(adset_ids):
            give = base + (1 if index < extra else 0)
            result[aid] = Money(give)
        return result

    def campaign_total_spent(self, campaign: Campaign, day_key: str) -> Money:
        spent = self._spent_per_adset(campaign, day_key)
        return sum_money([spent.get(aid, Money.zero()) for aid in campaign.adset_ids()])

    def is_over_budget(self, campaign: Campaign, day_key: str) -> bool:
        if not campaign.uses_cbo:
            return False
        budget = campaign.cbo_daily_budget
        assert budget is not None
        return self.campaign_total_spent(campaign, day_key).cents > budget.cents

