from __future__ import annotations

"""Integer-cents money type used everywhere budgets and spend are tracked.

Ad spend is billed in fractions of a cent on real platforms, but for pacing we
round each charge to whole cents and keep all arithmetic in integers. Using a
plain ``float`` for currency drifts after a few thousand additions, and a daily
budget check that drifts by a cent will either let an extra impression through
or throttle a campaign early. So everything below is integer-cent math with a
thin wrapper that prints nicely for the audit report.
"""

from dataclasses import dataclass


@dataclass(frozen=True, order=True)
class Money:
    """An amount in whole cents. Never negative for spend or budgets."""

    cents: int

    def __post_init__(self) -> None:
        if not isinstance(self.cents, int):
            raise TypeError("Money is integer cents only")

    @classmethod
    def zero(cls) -> "Money":
        return cls(0)

    @classmethod
    def from_dollars(cls, dollars: float) -> "Money":
        """Build from a dollar amount, rounding to the nearest cent.

        Round half away from zero so $0.005 becomes one cent and not zero; the
        naive ``round`` builtin uses banker's rounding which surprises finance.
        """

        scaled = dollars * 100.0
        if scaled >= 0:
            return cls(int(scaled + 0.5))
        return cls(-int(-scaled + 0.5))

    def add(self, other: "Money") -> "Money":
        return Money(self.cents + other.cents)

    def subtract(self, other: "Money") -> "Money":
        return Money(self.cents - other.cents)

    def is_zero(self) -> bool:
        return self.cents == 0

    def is_positive(self) -> bool:
        return self.cents > 0

    def is_negative(self) -> bool:
        return self.cents < 0

    def clamp_non_negative(self) -> "Money":
        return self if self.cents >= 0 else Money.zero()

    def min_with(self, other: "Money") -> "Money":
        return self if self.cents <= other.cents else other

    def max_with(self, other: "Money") -> "Money":
        return self if self.cents >= other.cents else other

    def to_dollars(self) -> float:
        return self.cents / 100.0

    def __str__(self) -> str:
        sign = "-" if self.cents < 0 else ""
        whole, frac = divmod(abs(self.cents), 100)
        return f"{sign}${whole}.{frac:02d}"

    def __repr__(self) -> str:
        return f"Money(cents={self.cents})"


def sum_money(amounts: list[Money]) -> Money:
    """Sum a list of money values, returning zero for an empty list."""

    total = 0
    for amount in amounts:
        total += amount.cents
    return Money(total)


def total_cents(amounts: list[Money]) -> int:
    return sum(amount.cents for amount in amounts)


def cents(value: int) -> Money:
    """Short constructor used by callers that already have integer cents."""

    return Money(int(value))

