from __future__ import annotations

"""Decides whether a pending spend may be charged under the daily budget.

This is the gate the billing path calls before recording a charge. It looks up
the budget that governs the ad set, asks the ledger how much has already been
spent on the relevant spend day, and allows the new charge only while the day's
total stays within budget. For a CBO campaign the governing budget is the
campaign's, and the "already spent" figure is the sum across every ad set in the
campaign for that day. For a non-CBO ad set it is that ad set's own budget and
its own spend.

The spend day is the calendar day the charge falls on in the account's
timezone. The engine derives that day from the incoming event's UTC instant and
asks the ledger for spend on that same day.
"""

from dataclasses import dataclass

from account_timezone import instant_to_wall
from budget_models import AdAccount, Campaign
from money import Money
from spend_event import SpendEvent
from spend_ledger import SpendLedger


@dataclass(frozen=True)
class PacingDecision:
    """The outcome of a budget check for one pending charge."""

    allowed: bool
    day_key: str
    governing_budget: Money | None
    spent_before: Money
    spent_after: Money
    reason: str

    def headroom(self) -> Money:
        if self.governing_budget is None:
            return Money.zero()
        return self.governing_budget.subtract(self.spent_before).clamp_non_negative()


class PacingEngine:
    """Budget gate for a single account."""

    def __init__(self, account: AdAccount, ledger: SpendLedger) -> None:
        self._account = account
        self._ledger = ledger

    @property
    def account(self) -> AdAccount:
        return self._account

    @property
    def ledger(self) -> SpendLedger:
        return self._ledger

    def _day_key_for_instant(self, instant: int) -> str:
        """The spend-day key the engine charges an event against.

        Derived from the charge instant on the platform clock so it lines up
        with how the ledger groups recorded spend.
        """

        wall = instant_to_wall(instant, 0)
        return f"{wall.year:04d}-{wall.month:02d}-{wall.day:02d}"

    def _governing_spend(
        self, campaign: Campaign, adset_id: str, day_key: str
    ) -> Money:
        """Spend already counted against the governing budget for the day."""

        return self._ledger.adset_spend(adset_id, day_key)

    def check(self, event: SpendEvent) -> PacingDecision:
        """Decide whether ``event`` may be charged without breaching budget."""

        campaign = self._account.campaign_of_adset(event.adset_id)
        adset = campaign.adset(event.adset_id)
        day_key = self._day_key_for_instant(event.charged_at)

        if not adset.is_eligible():
            spent = self._governing_spend(campaign, event.adset_id, day_key)
            return PacingDecision(
                allowed=False,
                day_key=day_key,
                governing_budget=campaign.daily_cap_for(event.adset_id),
                spent_before=spent,
                spent_after=spent,
                reason="adset_paused",
            )

        budget = campaign.daily_cap_for(event.adset_id)
        spent_before = self._governing_spend(campaign, event.adset_id, day_key)
        spent_after = spent_before.add(event.amount)

        if budget is None:
            return PacingDecision(
                allowed=True,
                day_key=day_key,
                governing_budget=None,
                spent_before=spent_before,
                spent_after=spent_after,
                reason="no_budget_configured",
            )

        if spent_after.cents <= budget.cents:
            return PacingDecision(
                allowed=True,
                day_key=day_key,
                governing_budget=budget,
                spent_before=spent_before,
                spent_after=spent_after,
                reason="within_budget",
            )

        return PacingDecision(
            allowed=False,
            day_key=day_key,
            governing_budget=budget,
            spent_before=spent_before,
            spent_after=spent_after,
            reason="would_exceed_daily_budget",
        )

    def allow(self, event: SpendEvent) -> bool:
        return self.check(event).allowed

    def charge(self, event: SpendEvent) -> PacingDecision:
        """Check the event and, if allowed, record it in the ledger."""

        decision = self.check(event)
        if decision.allowed:
            self._ledger.record(event)
        return decision

    def remaining_for_adset(self, adset_id: str, day_key: str) -> Money:
        """Budget headroom left for an ad set's governing budget on a day."""

        campaign = self._account.campaign_of_adset(adset_id)
        budget = campaign.daily_cap_for(adset_id)
        if budget is None:
            return Money.zero()
        spent = self._governing_spend(campaign, adset_id, day_key)
        return budget.subtract(spent).clamp_non_negative()

