from __future__ import annotations

"""A single charged spend event against an ad set.

The billing system emits one of these every time it charges for delivered
impressions or clicks. Each event carries the UTC instant it was charged, the
ad set it belongs to, and the amount in whole cents. The pacing engine consumes
a stream of these and decides whether the next one is allowed under the daily
budget. The timestamp is always UTC; the account's local day is derived from it.
"""

from dataclasses import dataclass

from money import Money


@dataclass(frozen=True)
class SpendEvent:
    """An immutable record of money charged to an ad set at a UTC instant."""

    event_id: str
    adset_id: str
    amount: Money
    charged_at: int  # absolute UTC instant (seconds since epoch)

    def __post_init__(self) -> None:
        if self.amount.is_negative():
            raise ValueError("spend amount cannot be negative")
        if not self.event_id:
            raise ValueError("event_id is required")
        if not self.adset_id:
            raise ValueError("adset_id is required")


def build_event(
    event_id: str,
    adset_id: str,
    amount_cents: int,
    charged_at: int,
) -> SpendEvent:
    """Construct a spend event from integer cents and a UTC instant."""

    return SpendEvent(
        event_id=event_id,
        adset_id=adset_id,
        amount=Money(amount_cents),
        charged_at=charged_at,
    )


def order_by_time(events: list[SpendEvent]) -> list[SpendEvent]:
    """Return events sorted by charge instant, then by id for stability."""

    return sorted(events, key=lambda e: (e.charged_at, e.event_id))


def total_amount(events: list[SpendEvent]) -> Money:
    total = 0
    for event in events:
        total += event.amount.cents
    return Money(total)


def filter_by_adset(events: list[SpendEvent], adset_id: str) -> list[SpendEvent]:
    return [e for e in events if e.adset_id == adset_id]

