from __future__ import annotations

"""Stores recorded spend events and answers "how much has this spent" queries.

The ledger is append-only and deduplicates by event id, so re-delivering the
same charge does not double-count. Callers ask it for the spend that counts
against a particular spend day, scoped to a single ad set or to a whole set of
ad sets (a campaign). The day a query is about is identified by a day key, and
the ledger uses the account timezone to decide which stored events fall inside
that day's window.

The day key passed in is the account-timezone local date. The ledger must group
events by the day they belong to in that zone, so that a charge near local
midnight counts against the correct budget.
"""

from account_timezone import AccountTimezone, instant_to_wall
from money import Money
from spend_event import SpendEvent


class SpendLedger:
    """An append-only, deduplicated store of spend events."""

    def __init__(self, timezone: AccountTimezone) -> None:
        self._timezone = timezone
        self._events: dict[str, SpendEvent] = {}

